from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.table_stack = []
        self.rows = []
        self.cur_row = None
        self.cur_cell = None
        self.done = False

    def in_target(self):
        return bool(self.table_stack) and self.table_stack[-1]

    def _close_cell(self):
        if self.cur_cell is not None:
            if self.cur_row is not None:
                self.cur_row.append(''.join(self.cur_cell))
            self.cur_cell = None

    def _close_row(self):
        self._close_cell()
        if self.cur_row is not None:
            self.rows.append(self.cur_row)
            self.cur_row = None

    def handle_starttag(self, tag, attrs):
        t = tag.lower()
        if t == 'table':
            cls = None
            for k, v in attrs:
                if k.lower() == 'class':
                    cls = v
            is_target = (cls == 'data-table') and not self.done
            self.table_stack.append(is_target)
        elif t == 'tr':
            if self.in_target():
                self._close_row()
                self.cur_row = []
        elif t == 'td':
            if self.in_target() and self.cur_row is not None:
                self._close_cell()
                self.cur_cell = []

    def handle_endtag(self, tag):
        t = tag.lower()
        if t == 'td':
            if self.in_target():
                self._close_cell()
        elif t == 'tr':
            if self.in_target():
                self._close_row()
        elif t == 'table':
            if self.in_target():
                self._close_row()
                self.done = True
            if self.table_stack:
                self.table_stack.pop()

    def handle_data(self, data):
        if self.cur_cell is not None:
            self.cur_cell.append(data)


def extract_data_table_rows(html):
    p = _TableParser()
    try:
        p.feed(html)
        p.close()
    except Exception:
        pass
    p._close_row()
    return p.rows

