def mean_by_position(records):
    sums = {}
    counts = {}
    for rec in records:
        for pos, val in enumerate(rec[1:], start=1):
            v = float(val)
            sums[pos] = sums.get(pos, 0.0) + v
            counts[pos] = counts.get(pos, 0) + 1
    result = {}
    for pos in sorted(sums):
        result['Position %d' % pos] = sums[pos] / counts[pos]
    return result

